private static ulong MultComplexity(uint baseLength, uint modulusLength, bool isEip7883Enabled)
{
    uint max = baseLength > modulusLength ? baseLength : modulusLength;
    ulong words = ((ulong)max + 7u) >> 3; // ceil(max/8)
    ulong sq = words * words;
    if (isEip7883Enabled)
    {
        return max > LengthSize  // LengthSize = 32
            ? (sq << 1)  // 2 * words^2 for large inputs
            : 16UL;      // constant floor = 16 for small inputs
    }
    return sq;
}
// With EIP-7883: always returns >= 16 (constant floor for max <= 32, 2*words^2 for max > 32)
// words = ceil(max/8) >= ceil(0/8) = 0, but floor clamps to 16
